/**
 * FollowPointer: eases the object toward the pointer every frame.
 *
 * Generated by Pixi Editor (components v1). Plain TypeScript: safe to read, edit and commit.
 */
import { Component, getApp, isEditorPaused } from "../core";

export interface FollowPointerParams {
  /** How quickly it catches up to the pointer, 0–1 (1 = instant). */
  ease: number;
}

/** Eases the object toward the pointer every frame. Paused in Edit mode. */
export class FollowPointer extends Component<FollowPointerParams> {
  static readonly componentName = "FollowPointer";
  static readonly defaults: FollowPointerParams = { ease: 0.1 };

  update(): void {
    if (isEditorPaused()) return;
    const app = getApp();
    const parent = this.target.parent;
    if (!app || !app.renderer || !parent) return;
    const local = parent.toLocal(app.renderer.events.pointer.global);
    const ease = Math.min(1, Math.max(0, this.params.ease));
    this.target.x += (local.x - this.target.x) * ease;
    this.target.y += (local.y - this.target.y) * ease;
  }
}
